import {spanishLabel} from './branding.mjs';
import {journeysForPerson} from './document-model.mjs';
import {participantRole,vehicleForPerson} from './transport.mjs';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const vehicleText=(trip,p,direction)=>{const v=vehicleForPerson(trip,p,direction);return v?[v.name,v.driver?'Conductor: '+v.driver:"Conductor pendiente",v.phone?'Tel. '+v.phone:'',v.pickupLocation?"Recogida: "+v.pickupLocation:'',v.pickupTime||'',v.driverId===p.id?"Conduce este participante":''].filter(Boolean).join('\n'):"Sin asignar"};
export function exportRows(trip){return trip.people.map(p=>({
 'Nombre del participante':p.name,'Rol':spanishLabel(participantRole(p.role)),
 'Vuelos':p.travelMode==='Cotxe'?"Viaja en coche":journeysForPerson(trip,p.id).map(s=>[`${s.origin||"Origen pendiente"} → ${s.destination||"Destino pendiente"}`,s.service||'',s.departure?"Salida: "+s.departure:'',s.arrival?"Llegada: "+s.arrival:'',s.pending||s.stale?"Pendiente de revisión":''].filter(Boolean).join(' · ')).join('\n')||"Sin vuelos asociados",
 'Vehículo de ida':vehicleText(trip,p,'Anada'),'Vehículo de vuelta':vehicleText(trip,p,'Tornada'),'Notas':p.notes||''
}));}
export function exportHTML(trip){const rows=exportRows(trip),headers=["Nombre del participante",'Rol',"Vuelos","Vehículo de ida","Vehículo de vuelta","Notas"];return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(trip.name)} · Resumen del viaje</title><style>body{font:14px system-ui,sans-serif;color:#183530;margin:32px;background:#f7f9f7}header{border-bottom:4px solid #315e50;padding-bottom:18px;margin-bottom:24px}h1{margin:5px 0}p{color:#52665f}table{width:100%;border-collapse:collapse;background:white;table-layout:fixed}th{background:#183c36;color:white;text-align:left;font-size:12px}th,td{padding:12px;border:1px solid #d9e2dc;vertical-align:top;white-space:pre-wrap;overflow-wrap:anywhere}th:nth-child(1){width:14%}th:nth-child(2){width:7%}th:nth-child(3){width:30%}th:nth-child(4),th:nth-child(5){width:16%}tbody tr:nth-child(even){background:#f0f5f1}.note{white-space:pre-wrap}footer{margin-top:20px;font-size:11px;color:#64766e}@page{size:A4 landscape;margin:12mm}@media print{body{margin:0;background:white;font-size:10px}th,td{padding:7px}thead{display:table-header-group}tr{break-inside:avoid}h1{font-size:22px}}</style></head><body><header><p>EQUIP · RESUMEN DEL VIAJE</p><h1>${escape(trip.name)}</h1><p>${escape(trip.destination||'')} · ${escape(trip.start||'')} — ${escape(trip.end||'')} · ${rows.length} participantes</p></header><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${headers.map(h=>`<td>${escape(r[h])}</td>`).join('')}</tr>`).join('')}</tbody></table>${trip.notes?`<h2>Notas del viaje</h2><p class="note">${escape(trip.notes)}</p>`:''}<footer>Generado el ${escape(new Date().toLocaleString("es-ES"))}. Los datos pendientes se muestran explícitamente. Puedes imprimir este documento o guardarlo como PDF desde el navegador.</footer></body></html>`;}
export async function exportExcel(trip){const XLSX=await import('./vendor/xlsx.mjs');const headers=["Nombre del participante",'Rol',"Vuelos","Vehículo de ida","Vehículo de vuelta","Notas"];const ws=XLSX.utils.json_to_sheet(exportRows(trip),{header:headers});ws['!cols']=[{wch:30},{wch:14},{wch:90},{wch:38},{wch:38},{wch:55}];ws['!autofilter']={ref:ws['!ref']};ws['!rows']=[{hpt:24},...trip.people.map(()=>({hpt:90}))];const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,ws,"Participantes");const info=XLSX.utils.aoa_to_sheet([["Viaje",trip.name],["Destino",trip.destination||''],["Salida",trip.start||''],['Tornada',trip.end||''],["Notas generales",trip.notes||'']]);info['!cols']=[{wch:20},{wch:90}];XLSX.utils.book_append_sheet(book,info,"Viaje");return XLSX.write(book,{type:'array',bookType:'xlsx'});}
export const exportFilename=trip=>'resum-'+String(trip.name||'viatge').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-|-$/g,'').toLowerCase();
